6	import babelPresetTypeScript from "@babel/preset-typescript";
7	import type { BetterAuthOptions } from "@better-auth/core";
8	import { BetterAuthError } from "@better-auth/core/error";
9	import { loadConfig } from "c12";
10	import type { TsConfigResult } from "get-tsconfig";
11	import { createPathsMatcher, getTsconfig, parseTsconfig } from "get-tsconfig";
12	import type { JitiOptions } from "jiti";
13	import { addCloudflareVirtualModules } from "./cloudflare-virtual-modules";
14	import { addSvelteKitVirtualModules } from "./sveltekit-virtual-modules";
15	import { getViteAssetStub } from "./vite-virtual-modules";
16	
17	let possiblePaths = [
18		"auth.ts",
19		"auth.tsx",
20		"auth.js",
21		"auth.jsx",
22		"auth.server.js",
23		"auth.server.ts",
24		"auth/index.ts",
25		"auth/index.tsx",
26		"auth/index.js",
27		"auth/index.jsx",
28		"auth/index.server.js",
29		"auth/index.server.ts",
30	];
