32	possiblePaths = [
33		...possiblePaths,
34		...possiblePaths.map((it) => `lib/server/${it}`),
35		...possiblePaths.map((it) => `server/auth/${it}`),
36		...possiblePaths.map((it) => `server/${it}`),
37		...possiblePaths.map((it) => `auth/${it}`),
38		...possiblePaths.map((it) => `lib/${it}`),
39		...possiblePaths.map((it) => `utils/${it}`),
40	];
41	possiblePaths = [
42		...possiblePaths,
43		...possiblePaths.map((it) => `src/${it}`),
44		...possiblePaths.map((it) => `app/${it}`),
45	];
