47	type PathsMatcher = (specifier: string) => string[];
48	
49	/** Reads `references` from raw tsconfig JSON (stripped out by `parseTsconfig`). */
50	function readRawTsconfigReferences(
51		tsconfigPath: string,
52	): Array<{ path: string }> | undefined {
53		try {
54			const text = fs.readFileSync(tsconfigPath, "utf-8");
55			const stripped = text
56				.replace(/\\"|"(?:\\"|[^"])*"|(\/\/.*|\/\*[\s\S]*?\*\/)/g, (m, g) =>
57					g ? "" : m,
58				)
59				.replace(/,(?=\s*[}\]])/g, "");
60			const raw = JSON.parse(stripped);
61			return raw.references;
62		} catch {
63			return undefined;
64		}
65	}
66	
67	/** Recursively collects tsconfigs reachable via `references`. */
68	function collectReferencedTsconfigs(
69		tsconfigPath: string,
70		visited = new Set<string>(),
71	): TsConfigResult[] {
72		const result: TsConfigResult[] = [];
73		const refs = readRawTsconfigReferences(tsconfigPath);
74		if (!refs) return result;
75	
76		const configDir = path.dirname(tsconfigPath);
77		for (const ref of refs) {
78			const resolvedRef = path.resolve(configDir, ref.path);
79			const refTsconfigPath = resolvedRef.endsWith(".json")
80				? resolvedRef
81				: path.join(resolvedRef, "tsconfig.json");
82	
83			if (visited.has(refTsconfigPath)) continue;
84			visited.add(refTsconfigPath);
85	
86			try {
87				const refConfig = parseTsconfig(refTsconfigPath);
88				result.push({ path: refTsconfigPath, config: refConfig });
89			} catch {
90				continue;
91			}
92	
93			result.push(...collectReferencedTsconfigs(refTsconfigPath, visited));
94		}
95		return result;
96	}
97	
98	/**
99	 * Ordered `paths` matchers from the project tsconfig and any referenced
100	 * tsconfigs, following TypeScript canonical resolution semantics.
101	 * @see https://github.com/microsoft/TypeScript/blob/main/src/compiler/moduleNameResolver.ts
102	 */
103	function collectPathsMatchers(cwd: string): PathsMatcher[] {
104		const configName = fs.existsSync(path.join(cwd, "tsconfig.json"))
105			? "tsconfig.json"
106			: "jsconfig.json";
107		const tsconfig = getTsconfig(cwd, configName);
108		if (!tsconfig) return [];
109	
110		const matchers: PathsMatcher[] = [];
111		try {
112			const mainMatcher = createPathsMatcher(tsconfig);
113			if (mainMatcher) matchers.push(mainMatcher);
114			for (const refTsconfig of collectReferencedTsconfigs(tsconfig.path)) {
115				const refMatcher = createPathsMatcher(refTsconfig);
116				if (refMatcher) matchers.push(refMatcher);
117			}
118		} catch (error) {
119			console.error(error);
120			throw new BetterAuthError("Error parsing tsconfig.json");
121		}
122		return matchers;
123	}
124	
125	/**
126	 * Source file extensions jiti can load. Shared between the jiti `extensions`
127	 * option and `resolveCandidateFile` so both stay in sync.
128	 */
129	const SOURCE_EXTENSIONS = [
130		".ts",
131		".tsx",
132		".mts",
133		".cts",
134		".js",
135		".jsx",
136		".mjs",
137		".cjs",
138	] as const;
139	
140	const SOURCE_EXTENSIONS_SET: ReadonlySet<string> = new Set(SOURCE_EXTENSIONS);
141	
142	/** Probes a candidate as-is, with known extensions, and as a directory index. */
143	function resolveCandidateFile(candidate: string): string | undefined {
144		try {
145			if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
146				return candidate;
147			}
148		} catch {}
149		// A candidate that already has a known extension is either the exact
150		// target or does not exist; extension and index probing would be noise.
151		if (SOURCE_EXTENSIONS_SET.has(path.extname(candidate))) {
152			return undefined;
153		}
154		for (const ext of SOURCE_EXTENSIONS) {
155			const withExt = candidate + ext;
156			if (fs.existsSync(withExt)) return withExt;
157		}
158		for (const ext of SOURCE_EXTENSIONS) {
159			const asIndex = path.join(candidate, `index${ext}`);
160			if (fs.existsSync(asIndex)) return asIndex;
161		}
162		return undefined;
163	}
164	
165	function resolveWithMatchers(
166		specifier: string,
167		matchers: PathsMatcher[],
168	): string | undefined {
169		for (const matcher of matchers) {
170			for (const candidate of matcher(specifier)) {
171				const resolved = resolveCandidateFile(candidate);
172				if (resolved) return resolved;
173			}
174		}
175		return undefined;
176	}
177	
178	interface StringLiteralNode {
179		type: "StringLiteral";
180		value: string;
181	}
182	interface BabelNodePath<Node> {
183		node: Node;
184	}
185	interface BabelTypes {
186		isIdentifier(node: unknown): node is { name: string };
187		isImport(node: unknown): boolean;
188		isStringLiteral(node: unknown): node is StringLiteralNode;
189	}
190	
191	/**
192	 * Callees whose first string argument is a module specifier. `jitiImport` is
193	 * a jiti-side preprocessor artifact observed in the AST; revisit on jiti
194	 * major version bumps (the regression suite catches a rename but not the why).
195	 */
196	const LOADER_IDENTIFIERS = new Set(["require", "import", "jitiImport"]);
197	
198	/**
199	 * Rewrites aliased specifiers at AST level. Required because jiti's `alias`
200	 * option only supports prefix matching and cannot express mid-path wildcards.
201	 *
202	 * Matchers always take precedence over native resolution, mirroring
203	 * TypeScript's own `paths` → `node_modules` order.
204	 */
205	function createRewriteImportPathsPlugin(matchers: PathsMatcher[]) {
206		return ({ types: t }: { types: BabelTypes }) => {
207			const rewrite = (source: StringLiteralNode | null | undefined): void => {
208				if (!source) return;
209				// Vite asset/query imports have no file on disk; stub them first so a
210				// resolved alias prefix never sends them down the filesystem path.
211				const stub = getViteAssetStub(source.value);
212				if (stub) {
213					source.value = stub;
214					return;
215				}
216				const resolved = resolveWithMatchers(source.value, matchers);
217				if (resolved) source.value = resolved;
218			};
219			return {
220				visitor: {
221					ImportDeclaration(p: BabelNodePath<{ source: StringLiteralNode }>) {
222						rewrite(p.node.source);
223					},
224					ExportNamedDeclaration(
225						p: BabelNodePath<{ source: StringLiteralNode | null }>,
226					) {
227						rewrite(p.node.source);
228					},
229					ExportAllDeclaration(p: BabelNodePath<{ source: StringLiteralNode }>) {
230						rewrite(p.node.source);
231					},
232					ImportExpression(p: BabelNodePath<{ source: unknown }>) {
233						// Only string literal sources can be statically rewritten.
234						if (t.isStringLiteral(p.node.source)) rewrite(p.node.source);
235					},
236					CallExpression(
237						p: BabelNodePath<{
238							callee: unknown;
239							arguments: unknown[];
240						}>,
241					) {
242						const { callee, arguments: args } = p.node;
243						const first = args[0];
244						if (!t.isStringLiteral(first)) return;
245						const isKnownLoader =
246							(t.isIdentifier(callee) && LOADER_IDENTIFIERS.has(callee.name)) ||
247							t.isImport(callee);
248						if (!isKnownLoader) return;
249						rewrite(first);
250					},
251				},
252			};
253		};
254	}
255	
256	/** Virtual module aliases; real tsconfig paths go through the babel plugin. */
257	function getVirtualModuleAliases(): Record<string, string> {
258		const result: Record<string, string> = {};
259		addSvelteKitVirtualModules(result);
260		addCloudflareVirtualModules(result);
261		return result;
262	}
263	/**
264	 * .tsx files are not supported by Jiti.
265	 */
266	const jitiOptions = (cwd: string): JitiOptions => {
267		const matchers = collectPathsMatchers(cwd);
268		// The plugin always runs: even with no tsconfig paths, it stubs Vite asset
269		// and query imports (`?raw`, `.css`, `.svg`, ...) that jiti cannot load.
270		const plugins = [createRewriteImportPathsPlugin(matchers)];
271		return {
272			transformOptions: {
273				babel: {
274					presets: [
275						[
276							babelPresetTypeScript,
277							{
278								isTSX: true,
279								allExtensions: true,
280							},
281						],
282						[babelPresetReact, { runtime: "automatic" }],
283					],
284					plugins,
285				},
286			},
287			extensions: [...SOURCE_EXTENSIONS],
288			alias: getVirtualModuleAliases(),
289		};
290	};
291	
292	const isDefaultExport = (
293		object: Record<string, unknown>,
294	): object is BetterAuthOptions => {
295		return (
296			typeof object === "object" &&
297			object !== null &&
298			!Array.isArray(object) &&
299			Object.keys(object).length > 0 &&
300			"options" in object
301		);
302	};
303	export async function getConfig({
304		cwd,
305		configPath,
306		shouldThrowOnError = false,
307	}: {
308		cwd: string;
309		configPath?: string;
310		shouldThrowOnError?: boolean;
311	}) {
312		try {
313			let configFile: BetterAuthOptions | null = null;
314			if (configPath) {
315				let resolvedPath: string = path.join(cwd, configPath);
316				if (existsSync(configPath)) resolvedPath = configPath; // If the configPath is a file, use it as is, as it means the path wasn't relative.
317				const { config } = await loadConfig<
318					| {
319							auth: {
320								options: BetterAuthOptions;
321							};
322					  }
323					| {
324							options: BetterAuthOptions;
325					  }
326				>({
327					configFile: resolvedPath,
328					dotenv: {
329						fileName: [".env", ".env.local"],
330					},
331					jitiOptions: jitiOptions(cwd),
332					cwd,
333				});
334				if (!("auth" in config) && !isDefaultExport(config)) {
335					if (shouldThrowOnError) {
336						throw new Error(
337							`Couldn't read your auth config in ${resolvedPath}. Make sure to default export your auth instance or to export as a variable named auth.`,
338						);
339					}
340					console.error(
341						`[#better-auth]: Couldn't read your auth config in ${resolvedPath}. Make sure to default export your auth instance or to export as a variable named auth.`,
342					);
343					process.exit(1);
344				}
345				configFile = "auth" in config ? config.auth?.options : config.options;
346			}
347	
348			if (!configFile) {
349				for (const possiblePath of possiblePaths) {
350					try {
351						const { config } = await loadConfig<{
352							auth: {
353								options: BetterAuthOptions;
354							};
355							default?: {
356								options: BetterAuthOptions;
357							};
358						}>({
359							configFile: possiblePath,
360							dotenv: {
361								fileName: [".env", ".env.local"],
362							},
363							jitiOptions: jitiOptions(cwd),
364							cwd,
365						});
366						const hasConfig = Object.keys(config).length > 0;
367						if (hasConfig) {
368							configFile =
369								config.auth?.options || config.default?.options || null;
370							if (!configFile) {
371								if (shouldThrowOnError) {
372									throw new Error(
373										"Couldn't read your auth config. Make sure to default export your auth instance or to export as a variable named auth.",
374									);
375								}
376								console.error("[#better-auth]: Couldn't read your auth config.");
377								console.log("");
378								console.log(
379									"[#better-auth]: Make sure to default export your auth instance or to export as a variable named auth.",
380								);
381								process.exit(1);
382							}
383							break;
384						}
385					} catch (e) {
386						if (
387							typeof e === "object" &&
388							e &&
389							"message" in e &&
390							typeof e.message === "string" &&
391							e.message.includes(
392								"This module cannot be imported from a Client Component module",
393							)
394						) {
395							if (shouldThrowOnError) {
396								throw new Error(
397									`Please remove import 'server-only' from your auth config file temporarily. The CLI cannot resolve the configuration with it included. You can re-add it after running the CLI.`,
398								);
399							}
400							console.error(
401								`Please remove import 'server-only' from your auth config file temporarily. The CLI cannot resolve the configuration with it included. You can re-add it after running the CLI.`,
402							);
403							process.exit(1);
404						}
405						if (shouldThrowOnError) {
406							throw e;
407						}
408						console.error("[#better-auth]: Couldn't read your auth config.", e);
409						process.exit(1);
410					}
411				}
412			}
413			return configFile;
414		} catch (e) {
415			if (
416				typeof e === "object" &&
417				e &&
418				"message" in e &&
419				typeof e.message === "string" &&
420				e.message.includes(
421					"This module cannot be imported from a Client Component module",
422				)
423			) {
424				if (shouldThrowOnError) {
425					throw new Error(
426						`Please remove import 'server-only' from your auth config file temporarily. The CLI cannot resolve the configuration with it included. You can re-add it after running the CLI.`,
427					);
428				}
429				console.error(
430					`Please remove import 'server-only' from your auth config file temporarily. The CLI cannot resolve the configuration with it included. You can re-add it after running the CLI.`,
431				);
432				process.exit(1);
433			}
434			if (shouldThrowOnError) {
435				throw e;
436			}
437	
438			console.error("Couldn't read your auth config.", e);
439			process.exit(1);
440		}
441	}
