const stripSourceExtension = (p: string) => {
	const ext = path.extname(p);
	return SOURCE_EXTENSIONS_SET.has(ext) ? p.slice(0, -ext.length) : p;
};

/**
 * Returns the missing relative specifier when `error` is a `MODULE_NOT_FOUND`
 * for a `./` or `../` import that resolves (from an importing file) to exactly
 * `outputPath`, ignoring source extensions.
 */
function isMissingOutputImport(
	error: unknown,
	outputPath: string,
	fallbackImporters: string[],
): boolean {
	if (typeof error !== "object" || error === null) return false;
	const { code, message, requireStack } = error as {
		code?: unknown;
		message?: unknown;
		requireStack?: unknown;
	};
	if (code !== "MODULE_NOT_FOUND" || typeof message !== "string") return false;
	const specifier = /Cannot find module '([^']+)'/.exec(message)?.[1];
	if (!specifier || !/^\\.\\.?\\//.test(specifier)) return false;
	const importers = [
		...(Array.isArray(requireStack)
			? requireStack.filter((f): f is string => typeof f === "string")
			: []),
		...fallbackImporters,
	];
	const target = stripSourceExtension(outputPath);
	return importers.some(
		(importer) =>
			stripSourceExtension(path.resolve(path.dirname(importer), specifier)) ===
			target,
	);
}

export async function getConfig({
	cwd,
	configPath,
	outputPath,
	shouldThrowOnError = false,
}: {
	cwd: string;
	configPath?: string;
	outputPath?: string;
	shouldThrowOnError?: boolean;
}) {
	const resolvedOutputPath = outputPath
		? path.resolve(cwd, outputPath)
		: undefined;

	/**
	 * Loads the config. If it fails because it imports the not-yet-generated
	 * output file, creates an empty placeholder and retries once.
	 */
	const load = async <T extends Record<string, any>>(
		configFile: string,
	): Promise<{ config: T }> => {
		const attempt = () =>
			loadConfig<T>({
				configFile,
				dotenv: {
					fileName: [".env", ".env.local"],
				},
				jitiOptions: jitiOptions(cwd),
				cwd,
			});
		try {
			return await attempt();
		} catch (e) {
			if (
				!resolvedOutputPath ||
				existsSync(resolvedOutputPath) ||
				!isMissingOutputImport(e, resolvedOutputPath, [
					path.resolve(cwd, configFile),
				])
			) {
				throw e;
			}
			fs.mkdirSync(path.dirname(resolvedOutputPath), { recursive: true });
			fs.writeFileSync(resolvedOutputPath, "");
			try {
				return await attempt();
			} catch (retryError) {
				fs.rmSync(resolvedOutputPath, { force: true });
				throw retryError;
			}
		}
	};

